const text = String($json.body?.message ?? $json.message ?? '').trim();
const blocked = /(sign (this|the)|represent me|representing me|court|file (a|the) lawsuit|legal advice|act as my lawyer|attorney[- ]client)/i.test(text);
return [{json:{...$json, message:text, compliance:{allowed:!blocked, reason:blocked?'Licensed legal counsel required for representation, legal advice, filing, or signing.':'Information-only legal education permitted.'}}}];
